-- Add the Japanese Mega Dream ex set as a native JP checklist.
-- Additive only: existing set, card, and variant rows are never updated or deleted.

insert into public.card_sets (
  series_name, set_name, set_code, language, release_date,
  advertised_card_count, checklist_source_url, checklist_scope_note, is_public
)
select 'MEGA', 'MEGA Dream ex', 'M2a', 'JP', date '2025-11-28', 250,
       'https://www.pokemon-card.com/ex/m2a/index.html',
       '250 numbered cards: 193 main-set cards and 57 secret cards. Native Japanese checklist; card scans sourced from TCG Collector.',
       true
where not exists (select 1 from public.card_sets where language='JP' and set_code='M2a')
on conflict (set_name, language) do nothing;

with card_data(collector_number,card_name,card_type,rarity_label,element_types,guide_order,image_url,source_url) as (
