insert into public.cards (
  card_set_id,collector_number,card_name,card_type,rarity_label,element_types,
  guide_order,image_url,image_source_url,source_url
)
select target_set.id, card_data.collector_number, card_data.card_name, card_data.card_type,
       card_data.rarity_label, card_data.element_types, card_data.guide_order,
       card_data.image_url, 'https://www.tcgcollector.com/sets/11678/mega-dream-ex', card_data.source_url
from card_data cross join target_set
where not exists (
  select 1 from public.cards c where c.card_set_id=target_set.id and c.collector_number=card_data.collector_number
)
on conflict (card_set_id,collector_number) do nothing;

insert into public.card_print_variants (
  card_id,variant_key,variant_label,finish_code,checklist_group,is_master_set_target
)
select c.id,'normal','Normale','normal',case when c.guide_order <= 193 then 'main' else 'secret' end,true
from public.cards c
join public.card_sets s on s.id=c.card_set_id
where s.language='JP' and s.set_code='M2a'
  and not exists (select 1 from public.card_print_variants v where v.card_id=c.id and v.variant_key='normal')
on conflict (card_id,variant_key) do nothing;
